(window.FREALLY_I18N = window.FREALLY_I18N || {})["ko"] = {"hero.headline":"<span class=\"hl-muted\">파일을 바이트 하나까지 그대로.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">복사합니다.</span>","hero.cycle":"복사합니다.|옮깁니다.|동기화합니다.|검증합니다.","hero.sub":"체크섬 검증, 크래시 후 재개, 양방향 동기화, 실행 취소, 자체 파일 서버를 갖춘 Windows, macOS, Linux용 데스크톱 파일 복사 도구입니다. 계정도, 원격 측정도, AI도 없습니다.","hero.chipLanguages":"18개 언어","hero.chipCli":"명령줄","what.title":"이것이 무엇인가","what.p1":"큰 폴더를 시스템 기본 복사 대화 상자로 복사하면 알 수 있는 것이 거의 없습니다. 체크섬도 없고, 이미 있는 파일을 어떻게 처리할지 정할 수도 없으며, 도중에 전원이 나가면 되돌릴 방법도 없습니다.","what.p2":"Freally File Manager는 그런 일을 믿고 맡길 수 있도록 만든 복사 도구입니다. 창에 파일을 끌어다 놓고 대상을 고르면, 시스템에서 가장 빠른 복사 경로로 복사합니다. 검증을 켜면 모든 복사본을 다시 읽어 원본의 체크섬과 대조합니다.","what.p3":"복사 기능 주위에는 그다음에 필요한 모든 것이 있습니다. 다시 실행하고 실행 취소할 수 있는 모든 작업의 기록, 체크섬 도구, 양방향 동기화와 라이브 미러, 스냅샷, 내장 파일 서버, 그리고 스크립트용 명령줄입니다.","features.title":"담긴 것","features.copy.title":"바이트 단위로 정확한 복사","features.copy.body":"모든 파일은 시스템 자체의 빠른 경로를 통해 바이트 하나까지 그대로 복사되며, 이를 지원하는 드라이브에서는 즉시 복제됩니다. 어떤 작업이든 일시 중지, 다시 시작, 취소할 수 있고, 파일이 이미 있을 때 어떻게 할지는 시작하기 전에 정합니다.","features.verify.title":"원할 때 검증","features.verify.body":"검증을 켜면 각 복사본을 다시 읽어 CRC32와 xxHash3부터 SHA-256과 BLAKE3까지 8가지 체크섬 중 하나로 원본과 대조합니다. 불일치는 숨겨지지 않고 반드시 보고됩니다.","features.resume.title":"정전에도 살아남습니다","features.resume.body":"저널이 각 복사가 어디까지 진행되었는지 기록합니다. 크래시나 재부팅 후에는 이미 쓰인 부분을 확인하고, 처음부터 다시 시작하는 대신 그 지점부터 복사를 이어 갑니다.","features.sync.title":"양방향 동기화","features.sync.body":"두 폴더를 양방향으로 맞춰 두거나, 한쪽을 다른 쪽에 미러링하세요. 양쪽에서 모두 바뀐 파일은 충돌로 처리되어, 두 버전이 모두 보존되고 선택은 당신이 합니다.","features.history.title":"기록과 실행 취소","features.history.body":"모든 작업이 기록됩니다. 다시 실행하거나, 실패한 파일만 재시도하거나, 마지막 복사나 이동을 실행 취소하세요. 실행 취소된 복사본은 바로 삭제되지 않고 휴지통으로 갑니다.","features.checks.title":"언제든 파일 확인","features.checks.body":"어떤 파일이든 8가지 체크섬으로 해시하고, .sha256이나 .sfv 파일을 만들고 확인하고, 몇 달 뒤에 폴더를 그 복사본과 비교하고, 무엇이 복사되었는지 담은 서명된 보고서를 내보낼 수 있습니다.","features.server.title":"나만의 파일 서버","features.server.body":"WebDAV, 일반 HTTP, S3 호환 API 또는 SFTP로 폴더를 다른 컴퓨터에 제공하세요. 원하면 읽기 전용으로 두고, 암호나 토큰으로 보호할 수 있습니다.","features.free.title":"무료, 프라이버시 보호, AI 없음","features.free.body":"계정도, 원격 측정도, 머신러닝도 없습니다. 파일은 당신이 보낸 곳으로만 가며, 하루 한 번의 업데이트 확인은 끌 수 있습니다.","ladder.title":"1.0으로 가는 길","ladder.intro":"버전마다 한 줄씩, 오래된 것부터. 모두 완료되었습니다. 빌드되고, 테스트되고, 태그가 붙었습니다.","ladder.rung.v0.19.84":"첫 릴리스: 선택적 검증이 가능한 바이트 단위로 정확한 복사, 크래시 후 재개, 기록, 양방향 동기화와 라이브 미러, 파일 서버와 명령줄, 18개 언어 지원.","ladder.rung.v0.19.85":"라이브러리: 백업하고 비교하고 복원할 수 있는 중복 제거 스냅샷, 그리고 restic, Borg, Kopia에서 가져오거나 그쪽으로 내보낼 수 있는 저장소.","ladder.rung.v0.20.0":"안전망: 마지막 복사나 이동 실행 취소, 휴지통으로 삭제, 실패한 파일만 재시도, 체크섬 파일, 작업이 끝나면 드라이브 꺼내기.","ladder.rung.v0.22.0":"해시, 보고서, 예약: 해시 검사기, 서명된 복사 보고서, 재검증, 손상된 미디어 복구, 예약, 즐겨찾기, 휴대용 모드, 접근성.","ladder.rung.v1.0.0":"정확성 릴리스: 코드를 섹션별로 살펴본 전면 검토와, 거기서 나온 모든 수정.","ladder.note":"완료된 버전은 빌드되고 태그가 붙어 있습니다. 이 사이트에서 다운로드할 수 있는 버전은 없습니다. 여기에는 아직 다운로드가 없습니다.","honest.title":"대부분의 사이트가 맨 아래에 적어 두는 것들","honest.verify.title":"검증은 켜기 전까지 꺼져 있습니다","honest.verify.body":"복사본을 확인한다는 것은 한 번 더 읽는다는 뜻이므로, 기본 동작이 아니라 설정입니다. ‘설정 → 전송’에서 체크섬을 고르면 그 뒤의 모든 복사가 확인됩니다.","honest.notYet.title":"1.0이 아직 하지 못하는 두 가지","honest.notYet.body":"파일을 안전하게 완전 삭제(파쇄)할 수 없고, 클라우드 저장소로 복사할 수도 없습니다. 설정에는 이미 두 기능의 자리가 있지만, 버전 1.0.0에서는 어느 쪽도 연결되어 있지 않습니다.","honest.network.title":"온라인에 접속하는 경우","honest.network.body":"내 드라이브 사이의 복사, 검증, 삭제는 네트워크 요청을 하지 않습니다. 파일 서버나 클라우드 계정 테스트처럼 당신이 설정한 일을 위해, 그리고 시작할 때 하루 최대 한 번 업데이트를 확인하기 위해 온라인에 접속하며, 업데이트 확인은 ‘설정 → 업데이트’에서 끌 수 있습니다.","honest.downloads.title":"여기에는 아직 다운로드가 없습니다","honest.downloads.body":"이 사이트에는 설치 프로그램도, 미리보기 빌드도, 다운로드 링크도 없습니다. 이것이 바뀌면 이 페이지에서 알려 드리겠습니다.","site.tagline":"파일을 바이트 하나까지 그대로 복사하고, 옮기고, 동기화하고, 검증합니다.","footer.licence":"독점 소프트웨어 — 모든 권리 보유. © Mike Weaver. 지금은 무료로 사용할 수 있지만, 향후 버전은 판매될 수 있습니다. 오픈소스는 아닙니다.","footer.yours":"당신이 복사하고, 동기화하고, 제공하는 파일은 당신의 것입니다. Freally File Manager의 제작자는 그 파일에 대해 어떠한 소유권도 주장하지 않습니다.","featuresPage.lead":"검증, 크래시 후 재개, 동기화, 실행 취소, 자체 파일 서버를 갖추고, 지금까지 실행한 모든 작업을 기록하는 바이트 단위로 정확한 파일 복사 도구.","featuresPage.version":"이 페이지는 현재 버전인 Freally File Manager 1.0.0을 설명합니다. 여기 나온 모든 것은 1.0.0에 들어 있습니다.","featuresPage.numbers.intro":"각 숫자는 버전 1.0.0의 코드에서 직접 센 것입니다. 올려 잡은 숫자는 없습니다.","featuresPage.numbers.hashes":"복사본 검증에 쓸 수 있는 체크섬","featuresPage.numbers.collisions":"이미 있는 파일에 대한 선택지","featuresPage.numbers.sidecars":"만들고 확인할 수 있는 체크섬 파일 형식","featuresPage.numbers.server":"폴더를 제공하는 방법: WebDAV, HTTP, S3, SFTP","featuresPage.numbers.systems":"운영체제: Windows, macOS, Linux","featuresPage.numbers.languages":"언어","featuresPage.numbers.ai":"AI 모델","featuresPage.numbers.price":"현재 가격","featuresPage.free.title":"지금은 무료","featuresPage.free.body":"Freally File Manager가 지금 하는 모든 것은 누구에게나 무료입니다. 유료 등급도, 구독도, 라이선스 키도, 계정도 없습니다.","featuresPage.cards.title":"버전 1.0이 하는 일","featuresPage.cards.copy.title":"복사 엔진","featuresPage.cards.copy.body":"각 시스템에서 가장 빠른 경로를 통한 바이트 단위로 정확한 복사와, 이를 지원하는 파일 시스템에서의 즉시 복제. 거대한 폴더도 메모리를 가득 채우지 않고 스트리밍되며, 이미 있는 파일을 어떻게 할지는 복사를 시작하기 전에 고릅니다. 둘 다 유지, 건너뛰기, 덮어쓰기, 더 새로우면 덮어쓰기, 내용이 다를 때만 덮어쓰기, 또는 묻기 중에서 고를 수 있습니다.","featuresPage.cards.verify.title":"복사 후 검증","featuresPage.cards.verify.body":"8가지 체크섬: CRC32, MD5, SHA-1, SHA-256, SHA-512, xxHash3-64, xxHash3-128, BLAKE3. 각 복사본을 다시 읽어 원본과 비교하며, 불일치가 있으면 그 파일은 모르는 사이에 통과되지 않고 실패로 처리됩니다.","featuresPage.cards.checks.title":"해시, 재검증, 체크섬 파일","featuresPage.cards.checks.body":"‘해시’ 패널은 붙여 넣은 체크섬과 파일을 대조합니다. ‘재검증’은 몇 달 뒤에도 바이트 하나 쓰지 않고 폴더를 그 복사본과 비교합니다. 폴더 전체에 대한 .md5, .sha1, .sha256, .sha512, .b3, .sfv 파일을 만들 수 있고, 그 파일을 창에 끌어다 놓으면 확인합니다.","featuresPage.cards.resume.title":"크래시와 재부팅 후 재개","featuresPage.cards.resume.body":"저널이 각 복사의 진행 상황을 기록합니다. 다음 실행 때 이미 쓰인 부분을 해시로 확인하고, 그 지점부터 복사를 이어 갑니다.","featuresPage.cards.history.title":"기록, 다시 실행, 실행 취소","featuresPage.cards.history.body":"모든 작업이 기록됩니다. 어떤 작업이든 다시 실행하거나, 실패한 파일만 재시도하거나, 서명된 보고서를 내보내거나, 마지막 복사나 이동을 실행 취소할 수 있습니다. 실행 취소된 복사본은 바로 삭제되지 않고 휴지통으로 갑니다.","featuresPage.cards.sync.title":"동기화와 라이브 미러","featuresPage.cards.sync.body":"양방향 동기화, 어느 방향으로든 미러, 또는 기여 전용. 충돌은 두 개의 파일로 보존되어 당신이 고를 수 있습니다. 라이브 미러는 폴더를 감시하다가 저장하는 모든 변경을 동기화합니다.","featuresPage.cards.server.title":"내장 파일 서버","featuresPage.cards.server.body":"어떤 폴더든 WebDAV, HTTP, S3 호환 API 또는 SFTP로 제공합니다. 설정이나 freally serve 명령에서 시작할 수 있고, 원하면 읽기 전용으로 두거나 토큰이나 암호로 보호할 수 있으며, Prometheus 메트릭 엔드포인트도 있습니다.","featuresPage.cards.library.title":"스냅샷과 백업","featuresPage.cards.library.body":"중복 제거 저장소는 파일의 각 버전을 한 번만 저장합니다. 타임라인을 둘러보고, 어떤 스냅샷이든 복원하고, 선택한 폴더를 필요할 때 백업하고, restic, Borg, Kopia의 저장소를 가져올 수 있습니다.","featuresPage.cards.salvage.title":"고장 나는 디스크 구하기","featuresPage.cards.salvage.body":"‘복구’는 고장 나는 드라이브의 파일에서 아직 읽을 수 있는 것은 모두 복사하고, 읽을 수 없는 부분은 0으로 채워 나머지가 제자리를 지키게 하며, 빈 구간의 지도를 남겨 두었다가 다음 실행 때 그 빈 구간만 재시도합니다.","featuresPage.cards.metadata.title":"모르는 사이에 잃는 것은 없습니다","featuresPage.cards.metadata.body":"희소 파일은 희소 파일 그대로 유지되고, 대체 데이터 스트림, 확장 속성, 인터넷에서 다운로드했다는 표시도 각 파일과 함께 옮겨 갑니다. Windows에서 다른 프로그램이 잠근 파일은 스냅샷에서 복사할 수 있습니다.","featuresPage.cards.desktop.title":"데스크톱의 일부","featuresPage.cards.desktop.body":"파일 탐색기, Finder, Nautilus, Dolphin, Thunar의 오른쪽 클릭 메뉴에서 복사하고 이동하며, 어디서든 Ctrl+Shift+V로 이 앱을 통해 붙여 넣고, 저장한 작업을 시스템 자체의 스케줄러로 예약할 수 있습니다.","featuresPage.cards.cli.title":"스크립트용 명령줄","featuresPage.cards.cli.body":"freally 명령은 복사, 이동, 검증을 하고, 실행 전에 작업을 계획하고, 폴더를 제공하고, 백업을 가져오며, 문서화된 종료 코드와 함께 JSON Lines 형식으로 결과를 보고합니다.","featuresPage.compare.title":"상용 도구와 나란히","featuresPage.compare.intro":"사람들이 파일을 복사하고, 확인하고, 동기화하고, 관리하려고 구입하는 상용 도구 6가지와 나란히 놓은 Freally File Manager 1.0.0. 다른 제품의 모든 칸은 각 제조사 자체 페이지에서 가져와 2026년 10월 2일에 확인했으며, 가격은 2026년 10월 기준 미국 정가입니다.","featuresPage.compare.feature":"기능","featuresPage.compare.row.price":"가격 (USD, 2026년 10월)","featuresPage.compare.freeToday":"지금은 무료","featuresPage.compare.legend.unknown":"확인 안 됨","featuresPage.compare.note.aud":"호주 달러로 판매","featuresPage.compare.note.eur":"유로로 판매","featuresPage.compare.note.updatesYear":"1년간 업데이트","featuresPage.compare.note.perYear":"연간, 최대 기기 5대","featuresPage.compare.row.verify":"각 복사본을 체크섬으로 확인","featuresPage.compare.legend.yes":"있음","featuresPage.compare.note.optional":"선택 사항, 체크섬 8가지","featuresPage.compare.legend.partly":"부분적","featuresPage.compare.note.checksumTool":"체크섬 도구는 있으나 복사할 때마다는 아님","featuresPage.compare.row.systems":"Windows, macOS, Linux 지원","featuresPage.compare.note.oldMac":"Mac 앱은 구버전","featuresPage.compare.note.webLinux":"Linux: 웹 인터페이스만","featuresPage.compare.row.resume":"크래시나 재부팅 후 복사 재개","featuresPage.compare.note.afterStop":"중지 후, 목록을 다시 열어서","featuresPage.compare.note.ftpOnly":"FTP만","featuresPage.compare.note.ftpDownloads":"FTP 다운로드만","featuresPage.compare.note.connectOnly":"GoodSync Connect 전송만","featuresPage.compare.row.sync":"충돌의 양쪽을 모두 보존하는 양방향 동기화","featuresPage.compare.note.byDate":"양방향, 날짜 기준","featuresPage.compare.note.noConflicts":"양방향, 충돌 처리는 문서화되지 않음","featuresPage.compare.note.newerWins":"더 새로운 파일이 우선","featuresPage.compare.row.server":"WebDAV, S3, SFTP로 폴더 제공","featuresPage.compare.note.ownProtocol":"다른 GoodSync 앱에만","featuresPage.compare.row.undo":"끝난 복사나 이동을 실행 취소","featuresPage.compare.note.keepsVersions":"교체된 파일 보관","featuresPage.compare.row.salvage":"고장 나는 드라이브에서 아직 읽을 수 있는 것을 구출","featuresPage.compare.row.report":"각 파일의 체크섬 보고서 내보내기","featuresPage.compare.note.signable":"서명 가능","featuresPage.compare.note.logNoSums":"체크섬 없는 로그","featuresPage.compare.note.logView":"로그 보기","featuresPage.compare.note.compareReport":"별도의 비교 보고서","featuresPage.compare.note.changeReport":"로그와 변경 보고서","featuresPage.compare.legend.no":"없음","featuresPage.compare.summaryTitle":"요약하면","featuresPage.compare.summary":"요약하면: 이 모든 것을 갖춘 것은 Freally File Manager뿐입니다. 여섯 제품 중 어느 것도 제조사 자체 페이지에 WebDAV, S3, SFTP 서버나 고장 나는 드라이브에서 파일을 구출하는 방법을 내세우지 않으며, 여섯 중 동기화 충돌 감지를 문서화한 것은 GoodSync뿐입니다.","featuresPage.compare.theyWinTitle":"다른 도구가 앞서는 점","featuresPage.compare.theyWin":"다른 도구가 앞서는 점: Directory Opus, Total Commander, ForkLift는 자체 창에서 모든 폴더를 탐색하고 정리할 수 있지만, Freally File Manager 1.0.0은 건네받은 파일만 다룹니다. TeraCopy와 Directory Opus는 파일을 안전하게 삭제할 수 있고, ForkLift, Beyond Compare, GoodSync는 클라우드 저장소로 복사하지만, Freally File Manager 1.0.0은 둘 다 하지 못합니다. TeraCopy는 체크섬도 더 많아서, 8가지에 비해 17가지입니다.","featuresPage.compare.asOf":"Freally File Manager 열은 버전 1.0.0이며, 가격은 현재 기준입니다. 지금은 무료이지만, 향후 버전은 판매될 수 있습니다. 다른 제품도 바뀝니다. 이 표는 2026년 10월 2일 기준입니다.","featuresPage.why.title":"왜 이렇게 만들었는가","featuresPage.why.exact.title":"바이트 하나까지 같거나, 아니면 실패","featuresPage.why.exact.body":"복사본은 원본과 같은 바이트이거나, 아니면 실패로 보고됩니다. 또한 읽는 도중에 바뀐 파일은 깨끗한 복사본인 척 넘어가지 않고, 선택에 따라 표시되거나, 다시 복사되거나, 실패 처리됩니다.","featuresPage.why.native.title":"시스템 자체의 빠른 경로","featuresPage.why.native.body":"모든 바이트를 자체 루프로 밀어 넣는 대신, Windows, macOS, Linux에 각자 아는 가장 빠른 방법으로 각 파일을 복사하도록 요청하고, 파일 시스템이 허용하면 파일을 즉시 복제합니다.","featuresPage.why.safe.title":"실수로 파괴되는 것은 없습니다","featuresPage.why.safe.body":"이동은 복사가 성공한 뒤에만 원본을 삭제하고, 실행 취소는 파일을 삭제하지 않고 휴지통으로 보내며, 복사된 뒤 바뀐 파일은 절대 건드리지 않습니다.","featuresPage.why.local.title":"당신의 컴퓨터에 머뭅니다","featuresPage.why.local.body":"원격 측정도, 계정도 없습니다. 파일은 당신이 보낸 곳으로만 가며, 설정 파일을 편집해도 원격 측정을 켤 수 없습니다.","featuresPage.why.noAi.title":"AI 없음","featuresPage.why.noAi.body":"판단하는 모든 것은 체크섬, 크기, 타임스탬프를 쓰는 평범하고 예측 가능한 코드에서 나옵니다. 머신러닝 라이브러리는 들어 있지 않습니다.","featuresPage.limits.heading":"한계를 솔직하게","featuresPage.limits.intro":"빈틈을 숨기는 기능 목록은 읽을 가치가 없습니다. 위의 모든 것은 버전 1.0.0에 있으며, 아래는 이 버전이 하지 못하는 것입니다.","featuresPage.limits.title":"1.0이 하지 않는 것","featuresPage.limits.verify":"‘설정 → 전송’에서 검증을 켜기 전까지는 복사본을 검증하지 않습니다.","featuresPage.limits.queue":"대기열의 작업 순서는 바꿀 수 없습니다. 각 작업은 추가되자마자 시작됩니다.","featuresPage.limits.portable":"휴대용 모드는 설정과 프로필을 앱 옆에 두지만, 기록, 재개 저널, 저장된 클라우드 암호는 앱이 실행되는 컴퓨터에 남습니다.","featuresPage.limits.shred":"파일을 안전하게 완전 삭제할 수 없습니다. ‘설정 → 보안 삭제’가 있지만, 1.0.0에는 그것을 통해 삭제하는 기능이 없습니다.","featuresPage.limits.cloud":"클라우드 저장소로 복사할 수 없습니다. ‘설정 → 원격’에서 클라우드 계정을 추가하고 테스트할 수는 있지만, 아직 그쪽으로 복사되지는 않습니다.","featuresPage.limits.downloads":"이 사이트에는 아직 다운로드가 없으며, 이 페이지에도 없습니다.","docs.intro":"Freally File Manager 버전 1.0.0 사용법입니다. 버튼, 탭, 메뉴는 앱에 표시되는 이름 그대로 적었습니다.","docs.start.title":"시작하기","docs.copy.title":"파일 복사","docs.move.title":"파일 이동","docs.verify.title":"복사본 검증","docs.history.title":"기록, 다시 실행, 실행 취소","docs.checks.title":"해시, 재검증, 체크섬 파일","docs.sync.title":"두 폴더 동기화","docs.filters.title":"복사할 대상 고르기","docs.shell.title":"오른쪽 클릭 메뉴와 붙여넣기 단축키","docs.library.title":"스냅샷과 백업","docs.salvage.title":"고장 나는 드라이브에서 파일 구출하기","docs.server.title":"파일 서버로 실행하기","docs.migrate.title":"restic, Borg, Kopia 저장소 가져오기","docs.settings.title":"설정","docs.shortcuts.title":"키보드 단축키","featuresPage.speed.title":"얼마나 빠른가","docs.trouble.title":"팁과 문제 해결","docs.report.title":"문제 신고","docs.privacy.title":"개인정보와 네트워크","docs.start.p1":"Freally File Manager는 Windows 11, macOS 12 이상, Linux용 데스크톱 앱입니다. 처음 열면 라이선스 계약이 표시됩니다. 끝까지 스크롤한 다음, 시작하려면 ‘동의함’을, 그렇지 않으면 ‘거부 후 종료’를 선택하세요.","docs.start.p2":"창은 ‘활동’ 패널 위에 있는 놓기 영역입니다. 헤더에는 ‘파일 추가’, ‘폴더 추가’, ‘목록 가져오기’가 있습니다. 푸터에는 ‘합계’, ‘기록’, ‘해시’, ‘재검증’, ‘복구’, ‘동기화’, ‘라이브러리’, ‘작업’과 설정을 여는 톱니바퀴가 있습니다.","docs.start.p3":"이 사이트에는 아직 다운로드가 없습니다.","docs.copy.s1":"파일이나 폴더를 창으로 끌어다 놓거나, 헤더에서 ‘파일 추가’ 또는 ‘폴더 추가’를 클릭하세요.","docs.copy.s2":"‘끌어다 놓은 항목 전송’ 대화 상자가 열립니다. ‘작업’은 ‘복사’로 둔 채 ‘대상 선택’을 클릭해 복사해 넣을 폴더를 고르세요.","docs.copy.s3":"‘파일이 이미 있는 경우’에서 이미 있는 파일을 어떻게 할지 고르세요. 둘 다 유지, 건너뛰기, 덮어쓰기, 더 새로울 때만 덮어쓰기, 내용이 다를 때만 덮어쓰기, 동일하면 건너뛰고 아니면 묻기, 또는 매번 묻기 중에서 고릅니다.","docs.copy.s4":"‘정렬’로 목록을 이름순이나 크기순으로 정렬하거나, 행을 끌어서 옮기세요. 파일은 항상 폴더보다 앞에 옵니다.","docs.copy.s5":"‘복사 시작’을 클릭하세요. 파일마다 ‘활동’ 패널에 진행률, 속도, 남은 시간이 표시된 행이 생기고, 헤더에는 합계가 표시됩니다.","docs.copy.p1":"작업을 일시 중지하려면 해당 행에 포커스를 두고 Space 키를 누르거나, 마우스 오른쪽 버튼으로 클릭해 ‘일시 중지’를 선택하세요. ‘다시 시작’은 이어서 진행하고 ‘취소’는 중지합니다. ‘모든 작업 일시 중지’, ‘모든 작업 다시 시작’, ‘모든 작업 취소’는 헤더에 있습니다.","docs.copy.p2":"대상에 모든 것을 담을 공간이 없으면 첫 바이트가 움직이기 전에 경고가 표시되고, 복사할 항목을 고를 수 있습니다. 대화 상자는 예약된 이름, 허용되지 않는 문자, 너무 긴 경로처럼 대상에서 쓸 수 없는 이름도 표시하고, 이름을 바꾸도록 제안합니다.","docs.copy.p3":"창 아래쪽의 ‘완료 시’를 사용하면 모든 작업이 끝났을 때 앱을 닫거나, 로그오프하거나, 시스템을 종료하거나, 절전 모드로 전환할 수 있습니다.","docs.move.p1":"이동은 복사와 같은 방식으로 합니다. ‘끌어다 놓은 항목 전송’ 대화 상자에서 ‘작업’을 ‘이동’으로 설정하고, 대상을 고른 뒤 ‘이동 시작’을 클릭하세요.","docs.move.p2":"각 파일은 먼저 복사되고, 원본은 복사가 성공한 뒤에만 삭제됩니다. 무엇이든 실패하면 원본은 그 자리에 그대로 남고, 해당 행은 실패로 표시됩니다.","docs.move.p3":"모든 이동을 되돌릴 수 있게 하려면 ‘설정 → 보안 삭제’에서 ‘이동한 원본 파일을 휴지통으로 보내기’를 켜세요. 그러면 원본은 삭제되지 않고 휴지통으로 갑니다.","docs.verify.p1":"검증은 켜기 전까지 꺼져 있습니다. ‘설정 → 전송’을 열고 ‘복사 후 검증’에서 체크섬을 고르세요. xxHash3가 가장 빠르고, BLAKE3는 강력하면서도 빠르며, SHA-256은 대부분의 다른 도구와 값이 일치합니다.","docs.verify.p2":"그때부터 모든 복사가 확인됩니다. 원본은 읽는 동안 해시되므로 두 번 읽지 않습니다. 복사본이 다 쓰이면 복사본도 해시하여 둘을 비교합니다.","docs.verify.p3":"일치하면 해당 행은 완료로 끝납니다. 일치하지 않으면 행이 실패하고, 예상 체크섬과 실제 체크섬이 표시됩니다. 큰 복사가 100%에서 멈춘 것처럼 보이면 아마 헤더에 ‘검증 중’이라고 표시되어 있을 것입니다. 확인이 아직 진행 중이라는 뜻입니다.","docs.history.p1":"푸터의 ‘기록’을 클릭하세요. 모든 작업이 종류, 원본, 대상, 크기, 상태, 소요 시간과 함께 나열되며, 종류, 상태, 텍스트로 목록을 거를 수 있습니다. ‘CSV 내보내기’로 목록을 저장합니다.","docs.history.p2":"작업에서 ‘다시 실행’으로 다시 실행하거나, ‘실패 재시도’로 실패한 파일만 복사하거나, ‘실패 내보내기’로 그 목록을 저장하거나, ‘재검증’하거나, ‘인증서’를 내보낼 수 있습니다. 인증서는 모든 파일의 체크섬, 크기, 상태를 담은 인쇄 가능한 HTML, CSV 또는 JSON 보고서로, 당신의 키로 서명할 수 있습니다.","docs.history.p3":"‘실행 취소’ 또는 Ctrl+Z는 무엇을 건드릴지 정확히 보여 준 뒤 가장 최근의 복사나 이동을 되돌립니다. 복사된 파일은 휴지통으로 가되, 복사된 내용과 여전히 일치할 때만 그렇습니다. 이동된 파일은 원래 있던 곳으로 돌아갑니다.","docs.history.p4":"역시 푸터에 있는 ‘합계’는 바이트, 파일, 작업의 누적 수치와 최근 30일의 차트를 보여 줍니다.","docs.checks.p1":"푸터의 ‘해시’는 해시 검사기를 엽니다. 파일이나 폴더를 추가하고, 알고리즘을 고른 뒤 ‘해시 계산’을 클릭하세요. 체크섬, 체크섬 파일의 한 줄, 또는 SFV 행을 붙여 넣어 대조하거나, 두 파일을 골라 동일한지 확인할 수 있습니다.","docs.checks.p2":"역시 푸터에 있는 ‘재검증’은 언제든, 아무것도 쓰지 않고 폴더를 그 복사본과 다시 비교합니다. 일치하는 파일, 다른 파일, 복사본에 없는 파일, 복사본에만 있는 파일, 읽을 수 없는 파일을 모두 보고합니다.","docs.checks.p3":"폴더 전체의 체크섬 파일을 만들려면 끝난 작업을 마우스 오른쪽 버튼으로 클릭하고 ‘체크섬 만들기 (SHA-256)’를 선택하세요. 확인하려면 .md5, .sha1, .sha256, .sha512, .b3 또는 .sfv 파일을 창에 끌어다 놓으세요. 그 파일에 나열된 모든 파일이 해시되고 결과가 표시됩니다.","docs.sync.s1":"푸터의 ‘동기화’를 클릭한 다음 ‘쌍 추가’를 클릭하세요.","docs.sync.s2":"쌍에 레이블을 붙이고, 왼쪽과 오른쪽 폴더를 고른 뒤 모드를 선택하세요. ‘양방향’, 왼쪽에서 오른쪽 또는 오른쪽에서 왼쪽으로 가는 ‘미러’, 또는 왼쪽에서 오른쪽으로 복사하고 절대 삭제하지 않는 ‘기여’ 중에서 고릅니다.","docs.sync.s3":"‘쌍 저장’을 클릭한 다음 ‘지금 실행’을 클릭하세요.","docs.sync.p1":"마지막 실행 이후 양쪽에서 모두 바뀐 파일이 있으면 아무것도 덮어쓰지 않습니다. 다른 쪽 버전은 동기화 충돌 파일로 그 옆에 보관되며, ‘충돌 보기’에서 왼쪽, 오른쪽, 또는 둘 다를 유지할 수 있습니다.","docs.sync.p2":"‘라이브 미러 시작’은 왼쪽 폴더를 감시하다가 변경을 저장할 때마다 다시 동기화합니다. 실행 중에는 쌍에 ‘감시 중’이 표시되며, ‘라이브 미러 중지’로 끝냅니다.","docs.filters.p1":"‘설정 → 필터’는 모든 복사에 적용됩니다. **/*.log나 **/node_modules 같은 포함 또는 제외 패턴, 크기와 날짜 제한, 숨김·시스템·읽기 전용 파일을 건너뛸지 여부를 정합니다. 제외 패턴과 일치하는 폴더는 통째로 건너뜁니다.","docs.filters.p2":"정확한 파일 목록을 복사하려면 헤더에서 ‘목록 가져오기’를 클릭하고 경로가 담긴 TXT, CSV 또는 JSON 파일을 고르세요. 한 폴더에 평평하게 복사하거나, 공통 루트 아래로 폴더 구조를 유지할 수 있습니다.","docs.filters.p3":"큰 복사를 하기 전에, ‘끌어다 놓은 항목 전송’ 대화 상자의 ‘계획 내보내기’는 복사가 무엇을 추가하고, 교체하고, 건너뛰고, 어디서 충돌을 만날지에 대한 보고서를 바이트 하나 움직이기 전에 저장합니다.","docs.shell.p1":"Freally File Manager는 오른쪽 클릭 메뉴에 ‘Copy with Freally File Manager’와 ‘Move with Freally File Manager’를 추가할 수 있습니다. Windows에서는 파일 탐색기, macOS에서는 Finder, Linux에서는 Nautilus, Dolphin, Thunar에 추가됩니다. Windows에서는 ‘설정 → 셸’에서 켜거나 끕니다.","docs.shell.p2":"평소처럼 Ctrl+C(Mac에서는 Cmd+C)로 파일을 복사한 다음, 어디서든 Ctrl+Shift+V(Mac에서는 Cmd+Shift+V)를 누르세요. 파일이 Freally File Manager의 대화 상자에서 열립니다. 단축키를 바꾸거나 끄려면 ‘설정 → 일반’으로 가세요.","docs.shell.p3":"Windows에서는 한 걸음 더 나아갈 수 있습니다. ‘설정 → 셸’의 ‘기본 복사 처리기 가로채기’는 파일 탐색기 자체의 복사와 붙여넣기를 Freally File Manager로 보내고, 그러면 붙여 넣을 때마다 일반 시스템 복사를 할지 검증된 복사를 할지 묻습니다. ‘Windows 복사 처리기로 되돌리기’를 클릭 한 번이면 원래대로 돌아갑니다.","docs.library.p1":"푸터의 ‘라이브러리’는 저장소를 엽니다. 각 파일의 내용은 중복 제거된 청크로 한 번만 저장되며, 모든 스냅샷이 하나의 타임라인에 표시됩니다. 헤더에는 디스크에 저장된 양과 그것이 나타내는 양이 표시됩니다.","docs.library.p2":"‘소스’에서 폴더를 추가하고 ‘지금 백업’을 클릭하면 스냅샷이 만들어집니다. 바뀌지 않은 폴더를 두 번째로 백업하면 공간을 거의 차지하지 않습니다. 각 소스는 모든 스냅샷, 최근 몇 개, 또는 순환 세트를 보관할 수 있고, 매시간, 매일, 매주 실행할 수 있습니다.","docs.library.p3":"‘스냅샷’에서 ‘복원’을 사용하면 스냅샷의 파일을 둘러보고, 대상을 고르고, 이미 있는 파일을 어떻게 할지 정할 수 있습니다. ‘잊기’는 스냅샷을 버리고, ‘공간 회수’는 더 이상 아무것도 쓰지 않는 청크를 비웁니다.","docs.salvage.p1":"푸터의 ‘복구’는 손상된 드라이브의 파일에서 아직 읽을 수 있는 것은 무엇이든 복사합니다. 파일을 고른 다음, 복사본을 쓸 위치를 고르세요.","docs.salvage.p2":"읽을 수 없는 부분은 점점 더 작은 조각으로 재시도한 뒤, 파일의 나머지가 제자리를 지키도록 0으로 채우고, 빈 구간의 지도를 복사본 옆에 저장합니다. 나중에 같은 파일에 ‘복구’를 다시 실행하면 빈 구간만 시도합니다.","docs.salvage.p3":"빈 구간이 있는 복구된 파일은 바이트 단위로 정확한 복사본이 아니며, 기록 항목에도 그렇게 적힙니다.","docs.server.p1":"Freally File Manager는 WebDAV, 일반 HTTP, S3 호환 API 또는 SFTP로 다른 컴퓨터에 폴더를 제공할 수 있습니다.","docs.server.s1":"‘설정 → 서버’를 열고 제공할 프로토콜에 체크하세요.","docs.server.s2":"바인드 주소를 설정하세요. 기본값인 127.0.0.1:8080은 이 컴퓨터에만 제공합니다. 0.0.0.0:8080이나 당신의 네트워크 주소는 방화벽이 허용하면 다른 컴퓨터에도 제공합니다.","docs.server.s3":"제공할 폴더를 고르고, 아무것도 업로드되거나 삭제되지 않아야 하면 ‘읽기 전용’에 체크한 뒤, 인증 방식을 고르세요. 없음, 베어러 토큰, 또는 사용자 이름과 암호 중에서 고릅니다.","docs.server.s4":"‘서버 시작’을 클릭하세요. 상태 줄에 주소가 표시되고, ‘메트릭’ 링크가 Prometheus 엔드포인트를 가리킵니다. ‘서버 중지’를 누르거나 앱을 종료하면 멈춥니다.","docs.server.protocol":"프로토콜","docs.server.connect":"연결 방법","docs.server.webdav":"Windows의 ‘네트워크 드라이브 연결’, Finder의 ‘서버에 연결’, GNOME Files 또는 davfs2","docs.server.http":"웹 브라우저, curl 또는 wget","docs.server.s3client":"AWS 명령줄, rclone 또는 아무 S3 라이브러리(사용자 이름과 암호를 액세스 키와 시크릿으로 사용)","docs.server.sftp":"sftp, scp, FileZilla, WinSCP 또는 rclone","docs.server.p2":"WebDAV와 HTTP는 한 주소에서 함께 실행할 수 있습니다. S3와 SFTP는 각각 별도의 서버가 필요하며, S3에는 토큰이 아니라 암호를 쓰거나 인증 없이 써야 합니다.","docs.server.p3":"인증 없이 네트워크에 열린 서버는 거기에 닿을 수 있는 무엇이든 읽을 수 있고, 읽기 전용이 아니라면 쓸 수도 있습니다. 내 컴퓨터 밖으로 제공할 때는 항상 토큰이나 암호를 설정하세요.","docs.server.p4":"화면이 없는 컴퓨터에서는 freally 명령으로 같은 일을 할 수 있습니다:","docs.migrate.p1":"freally migrate 명령은 다른 백업 도구의 저장소를 읽어 모든 파일을 다시 만들고, 이를 개방형 CDR-0 형식의 저장소에 저장하며, Freally File Manager 자체의 청크 분할로 다시 중복 제거합니다.","docs.migrate.p2":"각 가져오기 도구는 모든 파일을 바이트 하나까지 그대로 복원하는지 테스트를 거칩니다. CDR-0 형식은 이 사이트와 함께 공개된 사양서에 설명되어 있습니다.","docs.migrate.spec":"CDR-0 사양서 읽기","docs.settings.p1":"푸터의 톱니바퀴를 누르면 설정이 열립니다. 변경 사항은 다시 시작할 필요 없이 바로 적용됩니다. 가장 자주 쓰게 될 탭은 다음과 같습니다:","docs.settings.general":"일반: 언어, 앱 테마, 로그인 시 시작, 트레이로 최소화, 오류 표시 방식, 붙여넣기 단축키, 클립보드 감시.","docs.settings.transfer":"전송: 검증, 버퍼 크기, 한 번에 복사할 파일 수, 복제, 타임스탬프와 권한, 희소 파일, 잠긴 파일, 파일에 붙은 보안 표시.","docs.settings.filters":"필터: 포함하고 제외할 것.","docs.settings.shell":"셸: 오른쪽 클릭 메뉴, 그리고 Windows 자체의 복사를 대신 맡기.","docs.settings.network":"네트워크: 고정 또는 일정에 따른 속도 제한.","docs.settings.server":"서버: 내장 파일 서버.","docs.settings.updates":"업데이트: 하루 한 번의 업데이트 확인과, 지금 확인하는 버튼.","docs.settings.profiles":"프로필: 설정을 이름으로 저장하고, 서로 전환하고, 가져오거나 내보냅니다.","docs.shortcuts.keys":"키","docs.shortcuts.action":"기능","docs.shortcuts.paste":"복사한 파일을 어디서든 Freally File Manager를 통해 붙여넣기","docs.shortcuts.undo":"가장 최근의 복사 또는 이동 실행 취소","docs.shortcuts.pause":"포커스된 작업 일시 중지 또는 다시 시작","docs.shortcuts.escape":"맨 위의 대화 상자나 서랍 닫기","featuresPage.speed.intro":"2026년 4월 30일, Windows 11 노트북 한 대(Intel Core i9-13900HX, 메모리 32GB, PCIe 4.0 NVMe 드라이브)에서 같은 NTFS 드라이브 안의 복사를 측정했습니다. 각 수치는 여러 번 실행한 결과의 중앙값이며, 단위는 초당 MiB입니다. 높을수록 빠릅니다.","featuresPage.speed.workload":"복사한 것","featuresPage.speed.cmd":"Windows 복사 명령","featuresPage.speed.mixed":"파일 100개(100KB~150MB)가 든 폴더","featuresPage.speed.file512":"512MB 파일 1개","featuresPage.speed.file256":"256MB 파일 1개","featuresPage.speed.file10g":"10GB 파일 1개","featuresPage.speed.result":"파일이 든 폴더와 512MB 파일에서는 가장 빨랐고, 256MB와 10GB 파일에서는 Robocopy와 Windows 복사 명령보다 조금 느렸습니다. FastCopy와 TeraCopy보다는 모든 테스트에서 빨랐습니다.","featuresPage.speed.caveat":"컴퓨터 한 대와 드라이브 하나에서, 1.0.0 이전의 빌드로, 각 도구를 시작 시간까지 포함해 각자의 명령줄에서 실행하여 측정했습니다. 당신의 수치는 다를 것이며, 대상 드라이브가 가장 느린 부분이라면 모든 도구가 그 속도로 실행됩니다.","docs.trouble.slow.title":"복사가 왜 느린가요?","docs.trouble.slow.body":"복사가 도달해야 할 속도보다 느리게 진행되는 동안, 헤더에 원인을 알려 주는 작은 배지가 표시됩니다. 원본 디스크, 대상 디스크, 네트워크, 백신 검사기, 프로세서, 또는 발열입니다. 마우스를 올리면 자세한 내용이 나옵니다.","docs.trouble.stall.title":"복사가 100%에서 멈춥니다","docs.trouble.stall.body":"헤더에 ‘검증 중’이라고 표시되어 있다면 복사본을 체크섬과 대조하는 중입니다. 큰 파일에서는 정상입니다. 필요 없다면 ‘설정 → 전송’에서 검증을 끄세요.","docs.trouble.locked.title":"Windows에서 파일이 사용 중입니다","docs.trouble.locked.body":"파일은 다른 프로그램이 계속 쓸 수 있도록 열리며, 거부된 파일은 몇 번 재시도됩니다. 그래도 다른 프로그램이 독점적으로 잡고 있다면 그 프로그램을 닫거나, ‘설정 → 전송’에서 잠긴 파일을 스냅샷에서 복사하도록 선택하세요.","docs.trouble.permission.title":"권한이 거부됨","docs.trouble.permission.body":"권한 때문에 파일이 거부되면, Freally File Manager는 전체 목록에 대해 한 번의 관리자 확인으로 그 파일들을 재시도할 수 있으며, 승인하기 전에 어떤 파일을 건드릴지 정확히 보여 줍니다.","docs.trouble.changed.title":"복사 중 원본이 바뀜","docs.trouble.changed.body":"읽는 도중에 파일이 바뀌어서, 복사본에 이전 내용과 새 내용이 섞였을 수 있습니다. 기본적으로 그 파일은 표시만 됩니다. ‘설정 → 전송’에서 대신 한 번 다시 복사하거나 실패 처리하도록 할 수 있습니다.","docs.report.p1":"앱 자체가 오류를 일으키면 메시지 옆에 ‘신고’ 버튼이 나타납니다. 크래시가 난 뒤에는 다음 실행 때 ‘신고’ 또는 ‘닫기’를 고를 수 있습니다.","docs.report.p2":"‘신고’를 누르면 이 페이지가 브라우저에서 열리고, 기술적인 정보가 이미 채워져 있습니다. 읽을 수는 있지만 바꿀 수는 없습니다. 무엇을 하고 있었는지 적고, 원하면 답장을 받을 이메일 주소도 넣으세요.","docs.report.p3":"그 페이지에서 ‘보내기’를 누르지 않는 한 아무것도 전송되지 않으며, 백그라운드에서 무언가가 전송되는 일도 결코 없습니다. 보고서의 파일 경로는 줄여서 표시되며, 홈 폴더는 ~로 나타납니다.","docs.privacy.p1":"Freally File Manager에는 계정도 원격 측정도 없습니다. 설정의 원격 측정 스위치는 영구적으로 꺼져 있으며, 설정 파일에 직접 써넣은 값은 무시됩니다.","docs.privacy.p2":"내 드라이브에서 파일을 복사하고, 이동하고, 검증하는 일은 네트워크 요청을 하지 않습니다. 앱은 파일 서버나 클라우드 계정 테스트처럼 당신이 설정한 일을 위해, 그리고 시작할 때 하루 최대 한 번 업데이트를 확인하기 위해 온라인에 접속합니다. 업데이트 확인은 릴리스 목록만 읽고, 당신의 파일이나 경로는 전혀 보내지 않으며, ‘설정 → 업데이트’에서 끌 수 있습니다.","docs.privacy.p3":"AI는 들어 있지 않습니다. 판단하는 모든 것은 체크섬, 크기, 타임스탬프에서 나오며, 머신러닝 라이브러리는 포함되어 있지 않습니다.","kit.skip":"본문으로 건너뛰기","kit.nav.site":"사이트","kit.nav.home":"홈","kit.nav.features":"기능","kit.nav.documentation":"문서","kit.nav.changelog":"변경 로그","kit.nav.language":"언어","kit.nav.allApps":"모든 Freally 앱","kit.badge.done":"v1.0.0 완료","kit.cta.features":"모든 기능 보기","kit.cta.docs":"문서 읽기","kit.price":"Freally File Manager는 지금은 무료이지만 영원히 무료가 아닐 수도 있습니다. 향후 버전은 판매될 수 있습니다.","kit.noDownloads":"아직 다운로드는 없으며, 소스 코드는 비공개입니다.","kit.label.overview":"개요","kit.label.inside":"내부","kit.label.roadmap":"로드맵","kit.ladder.done":"완료","kit.label.honesty":"정직함","kit.family.label":"Freally 패밀리","kit.family.title":"<span class=\"hl-muted\">하나의 패밀리.</span> <span class=\"hl-bright\">여덟 개의 앱.</span>","kit.cta.label":"달라진 점","kit.cta.title":"<span class=\"hl-muted\">모든 버전을,</span> <span class=\"hl-bright\">기록으로.</span>","kit.cta.lede":"변경 로그에는 Freally File Manager에서 바뀐 모든 것이 버전별로, 18개 언어 모두로 담겨 있습니다.","kit.cta.changelog":"변경 로그 읽기","kit.footer.thisApp":"이 앱","kit.footer.family":"Freally 패밀리","kit.footer.home":"Freally Products","kit.status.devVersion":"개발 중 · v1.0.0","kit.head.features":"<span class=\"hl-muted\">할 수 있는 모든 것을,</span> <span class=\"hl-bright\">나란히 비교.</span>","kit.label.numbers":"숫자로 보기","kit.label.free":"지금은 무료","kit.label.compare":"비교","kit.label.principles":"원칙","kit.label.limits":"한계","kit.states.title":"상태의 의미","kit.states.done":"빌드하고 태그까지 달았지만, 이 사이트에서 내려받을 수는 없음","kit.states.ladder":"길의 모든 단계 보기","kit.head.documentation":"<span class=\"hl-muted\">작동 방식을,</span> <span class=\"hl-bright\">단계별로.</span>","kit.search.placeholder":"문서 검색","kit.docs.contents":"목차","kit.head.changelog":"<span class=\"hl-muted\">모든 변경을,</span> <span class=\"hl-bright\">버전별로.</span>","kit.changelog.lede":"최신순: Freally File Manager에서 바뀐 모든 것을, 이 사이트의 모든 언어로.","kit.changelog.versions":"버전","kit.search.none":"이 사이트에는 일치하는 것이 없습니다.","changelog.086fc6b9eb45":"<span class=\"release__meta\"><span class=\"release__ver\">v1.0.0</span><time class=\"release__date\" datetime=\"2026-08-22\">2026-08-22</time></span><span class=\"release__title\">정확성 릴리스</span>","changelog.490081990d07":"0.22.0의 모든 기능이 그대로 들어 있습니다. 달라진 점은 코드를 섹션별로 살펴본 전면 검토와, 거기서 나온 수정입니다. 그중 몇 가지는 오류를 한 번도 보여 주지 않은 채 데이터를 잃을 수 있는 문제였습니다.","changelog.1246fc93bca0":"수정됨","changelog.f485232d66fe":"<strong>바로 가기 폴더.</strong> 그 자체가 바로 가기(심볼릭 링크 또는 정션)인 폴더를 복사하면 아무것도 복사하지 않고 성공이라고 보고했으며, 동기화에서는 같은 결함으로 다른 쪽이 비워질 수 있었습니다. 이제 그런 폴더는 이유와 함께 거부됩니다.","changelog.b5ca80d81af1":"<strong>취소.</strong> 큰 폴더 복사를 취소하면 멈추지 않고 응답이 없어질 수 있었습니다. 이제 복사는 어느 시점에서든 취소할 수 있습니다.","changelog.02ca0292cb02":"<strong>S3 서버.</strong> AWS 명령줄이나 AWS 라이브러리로 업로드한 파일이 손상된 채 저장되었고, 약 8MB보다 큰 업로드는 아예 실패했습니다. 이제 둘 다 바이트 하나까지 그대로 도착하며, 중간에 끊긴 업로드는 저장되지 않고 거부됩니다.","changelog.00349386830d":"<strong>동기화 데이터베이스.</strong> 데이터베이스가 자기 폴더 중 하나 안에 있는 동기화 쌍은 그 데이터베이스를 동기화할 파일로 취급했고, 실행 도중에 삭제할 수 있었습니다.","changelog.f1d849633a99":"<strong>SFTP.</strong> SFTP 원격은 설정과 관계없이 모든 연결 테스트가 실패하여 전혀 연결되지 않았습니다. 이제 연결됩니다.","changelog.fd3bac863255":"<strong>암호화.</strong> 키를 준비할 수 없을 때 암호화가 일반 파일을 쓰는 방식으로 되돌아갈 수 있었습니다. 이제는 대신 작업을 중지합니다.","changelog.94d9edfe63bf":"<strong>읽기 전용 서버.</strong> 읽기 전용으로 설정한 서버에 한 종류의 요청은 여전히 쓸 수 있었습니다. 이제는 어떤 요청도 쓸 수 없습니다.","changelog.44b306c0f111":"<strong>진행률.</strong> 재개된 스캔이 잘못된 파일 수를 보고해서, 진행률 막대가 실제보다 앞서거나 뒤처졌습니다.","changelog.e19d94517f4b":"<strong>클라우드 로그인.</strong> 클라우드 계정 로그인이 눈에 보이는 이유 없이 실패할 수 있었고, 로그인을 중단할 때마다 스레드가 하나씩 누수되었습니다.","changelog.b4dfc2b6c682":"<strong>알려진 호스트.</strong> <code>known_hosts</code> 파일에 고정된 SFTP 서버는 목록의 첫 번째 키 유형이 아닌 다른 키 유형을 제시할 때마다 거부되었는데, 이는 대부분의 경우에 해당합니다.","changelog.042c3c3e6ae5":"<strong>알림.</strong> ntfy 알림이 메시지 대신 원시 코드로 도착했습니다.","changelog.6e72325e73e3":"<strong>대화 상자.</strong> 대화 상자 두 개가 열려 있을 때 Escape 키가 엉뚱한 것을 닫았고, 몇몇 설정 패널의 배치가 잘못되어 있었습니다.","changelog.acdd2a3d27ea":"<strong>관리자 확인 창(보안).</strong> Linux와 macOS에서, 당신의 권한으로 실행 중인 다른 프로그램이 암호 입력 창이 열려 있는 동안 자기 연결로 바꿔치기해, 당신이 승인하면 관리자로 실행되는 쪽이 그 프로그램이 될 수 있었습니다. 이제 확인 창은 그런 방식으로 탈취될 수 없습니다.","changelog.577866d56150":"<strong>대문자.</strong> Windows와 macOS에서 <code>Photo.jpg</code>와 <code>photo.jpg</code>는 같은 파일인데, 동기화는 이를 두 파일로 취급해 서로 덮어쓴 다음 남은 파일을 삭제할 수 있었습니다. 이제 다시 하나의 파일로 취급합니다.","changelog.f029d4f5e78c":"<strong>네트워크 드라이브.</strong> 네트워크 드라이브에 있는 폴더를 제공할 때, 느린 응답 하나가 다른 모든 요청을 붙잡아 두는 일이 더 이상 없습니다.","changelog.0ab356a87732":"<strong>도우미.</strong> 설치 프로그램에 관리자 권한이 필요한 일을 맡는 작은 도우미가 빠져 있어서, 설치된 앱에서는 권한 때문에 거부된 복사의 재시도나 오른쪽 클릭 메뉴 변경 같은 동작이 실패했습니다. 이제 도우미가 앱과 함께 제공됩니다.","changelog.87a38eb16185":"<strong>업데이트 확인.</strong> 모든 시스템에서 매번 실패했습니다. 이제 각 릴리스와 함께 게시되는 업데이트 목록을 읽습니다.","changelog.7a7604d1c245":"<strong>릴리스 노트.</strong> ‘업데이트’ 창이 변경 로그 링크를 네 번 반복했고, 그것도 작동하지 않는 텍스트로 보여 주었습니다. 이제 노트는 한 번만 나타나며, 브라우저에서 열리는 링크가 함께 있습니다.","changelog.9b82b2eda918":"코드에 없는 동작을 약속하던 <strong>문서</strong>를 바로잡았습니다.","changelog.d04ef101813e":"<span class=\"release__meta\"><span class=\"release__ver\">v0.22.0</span><time class=\"release__date\" datetime=\"2026-08-19\">2026-08-19</time></span><span class=\"release__title\">해시, 보고서, 예약, 휴대성</span>","changelog.6b02e0d363a4":"추가됨","changelog.68724824e3df":"<strong>해시 검사기.</strong> 어떤 파일이나 폴더든 8가지 알고리즘 중 하나로 해시하고, 체크섬을 붙여 넣어 대조하거나, 두 파일을 비교합니다. Windows에서는 오른쪽 클릭 메뉴에도 있습니다.","changelog.c3b19859a18b":"<strong>복사 보고서.</strong> 끝난 작업을 모든 파일의 체크섬, 크기, 상태가 담긴 인쇄 가능한 HTML 보고서, CSV 또는 JSON으로 내보내고, 원하면 당신의 키로 서명할 수 있어 누구나 Freally File Manager 없이도 확인할 수 있습니다.","changelog.19be8c01d283":"<strong>재검증.</strong> 몇 달 뒤에도 바이트 하나 쓰지 않고 폴더를 그 복사본과 다시 비교합니다: 일치하는 것, 다른 것, 빠진 것, 추가된 것.","changelog.66e001519d0e":"<strong>파일 이름 진단.</strong> 복사하기 전에 예약된 이름, 허용되지 않는 문자, 끝에 붙은 마침표와 공백, 너무 긴 경로, 대소문자만 다른 이름처럼 대상에서 쓸 수 없는 이름을 찾아 이름을 바꿉니다.","changelog.497980a00899":"<strong>목록에서 복사.</strong> TXT, CSV 또는 JSON 파일에서 경로 목록을 가져와, 평평하게 또는 폴더 구조를 유지한 채 복사할 파일로 사용합니다.","changelog.e70e0cbe1516":"<strong>계획 보고서.</strong> 복사가 무엇을 추가하고, 교체하고, 건너뛰고, 어디서 충돌을 만날지를 바이트 하나 움직이기 전에 내보냅니다.","changelog.650a70fbc1fb":"<strong>복구.</strong> 고장 나는 드라이브의 파일에서 아직 읽을 수 있는 것을 복사하고, 읽을 수 없는 부분은 0으로 채우고, 빈 구간의 지도를 남겨 나중에 그 빈 구간만 재시도합니다.","changelog.098ec7cfa416":"<strong>여러 파일에 한 번의 확인.</strong> 많은 파일이 권한 때문에 거부되었을 때, 목록 하나를 승인하면 한 번의 관리자 확인으로 모두 재시도합니다.","changelog.f231630df24f":"<strong>예약.</strong> 시스템 자체의 스케줄러(작업 스케줄러, launchd 또는 systemd)에서 항목을 만들고, 편집하고, 제거하며, 다음 실행 시각이 표시되고 관리자 권한은 필요 없습니다.","changelog.9d433f36b4af":"<strong>드라이브 대기열.</strong> 드라이브 감지가 틀렸을 때 바로잡습니다: 폴더들이 대기열 하나를 공유하게 하거나 따로 나누고, 각각의 작업자 수를 정합니다.","changelog.1be51474008d":"<strong>우선 처리.</strong> 한 작업이 끝나는 동안 실행 중인 다른 작업을 일시 중지했다가, 바로 그 작업들만 다시 시작합니다.","changelog.60c6175a344d":"<strong>즐겨찾기.</strong> 원본, 대상, 원본-대상 쌍을 북마크하고, 최근 쌍을 클릭 한 번으로 즐겨찾기에 둘 수 있습니다.","changelog.332cc7aa8523":"<strong>휴대용 모드.</strong> <code>--portable</code> 또는 앱 옆에 둔 표시 파일이 설정과 프로필을 앱 옆에 둡니다. 기록, 재개 저널, 저장된 클라우드 암호는 여전히 컴퓨터에 남으며, 설정에도 그렇게 안내됩니다.","changelog.2eb9e1222a1d":"<strong>접근성.</strong> Escape 키는 어디서든 맨 위의 대화 상자를 닫고, 동작 줄이기 설정은 모든 곳에서 존중되며, 포커스는 항상 보이고, 화면 낭독기는 실행 중, 완료, 실패 개수를 읽어 줍니다.","changelog.3c3c4afca24f":"<strong>원본 안정성 보호.</strong> 복사되는 동안 바뀐 파일은 선택에 따라 표시되거나, 한 번 다시 복사되거나, 실패 처리됩니다.","changelog.1d54a1bf0dc3":"<strong>로그인 시 시작.</strong> 트레이로 최소화된 상태로 시작하므로, 로그인하는 순간부터 오른쪽 클릭 메뉴, 붙여넣기 단축키, 예약이 작동합니다.","changelog.8dbeb02b73fb":"<strong>설정이 데이터를 버릴 수 있었던 문제.</strong> 설정을 저장하면 고정된 트레이 대상, 저장소, 클라우드 계정, 동기화 쌍 등이 기본값으로 초기화되었습니다. 이제 모든 그룹이 저장 후에도 유지되며, 테스트로 이를 확인합니다.","changelog.3e59c181d02c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.20.0</span><time class=\"release__date\" datetime=\"2026-07-20\">2026-07-20</time></span><span class=\"release__title\">안전망</span>","changelog.245019914a17":"<strong>실행 취소.</strong> Ctrl+Z 또는 기록 행의 ‘실행 취소’는 가장 최근의 복사나 이동을 되돌릴 때 무엇을 건드릴지 보여 준 다음 실행합니다. 복사된 파일은 휴지통으로 가되, 복사된 내용과 여전히 일치할 때만 그렇습니다.","changelog.6632a5f505b6":"<strong>휴지통으로 삭제</strong>, 그리고 이동한 파일의 원본을 삭제하는 대신 휴지통으로 보내는 옵션.","changelog.8242fb20ac7f":"<strong>실패 재시도.</strong> 작업에서 실패한 파일만 다시 복사하거나, 그 목록을 내보냅니다.","changelog.6b92af518239":"<strong>이미 있는 파일을 위한 두 가지 새 선택지.</strong> 내용이 다를 때만 덮어쓰기, 또는 동일하면 건너뛰고 아니면 묻기.","changelog.dca682f75970":"<strong>꺼내기.</strong> 작업이 쓴 드라이브를 안전하게 제거합니다.","changelog.e2eb082a0eff":"<strong>복사 중 절전 방지.</strong> 작업이 실행되는 동안 컴퓨터가 깨어 있습니다.","changelog.d2392c075c64":"<strong>체크섬 파일.</strong> 폴더 전체의 <code>.md5</code>, <code>.sha1</code>, <code>.sha256</code>, <code>.sha512</code>, <code>.b3</code>, <code>.sfv</code> 파일을 만들고, 그 파일을 창에 끌어다 놓으면 나열된 모든 파일을 확인합니다.","changelog.95c1ab071772":"<strong>Windows 복사 대신 맡기.</strong> 선택적으로 파일 탐색기 자체의 복사와 붙여넣기를 Freally File Manager로 보낼 수 있으며, 클릭 한 번으로 되돌릴 수 있습니다. 붙여 넣을 때마다 일반 시스템 복사나 검증된 복사를 고를 수 있습니다.","changelog.a20adfb45e43":"<strong>라이선스 계약.</strong> 앱을 처음 열 때 표시됩니다.","changelog.be1a948a30a9":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.85</span><time class=\"release__date\" datetime=\"2026-07-01\">2026-07-01</time></span><span class=\"release__title\">라이브러리와 백업 도구</span>","changelog.d28e3ce211c4":"<strong>라이브러리.</strong> 모든 스냅샷을 하나의 타임라인에, 저장된 양과 그것이 나타내는 양과 함께 보여 줍니다: 선택한 폴더를 백업하고, 어떤 스냅샷이든 원하는 곳으로 복원하세요.","changelog.eeb0847e8169":"<strong>압축되고 정리된 저장 공간.</strong> 스냅샷을 압축할 수 있고, 유지 관리가 더 이상 아무것도 쓰지 않는 공간을 회수하고 컴팩션하며, 오래 걸리는 작업은 모두 ‘작업’에 표시됩니다.","changelog.c73e54bfcf32":"<strong>비교와 보고서.</strong> 두 스냅샷을 비교하고, 저장소의 통계와 차트를 봅니다.","changelog.f9c43f8de8b1":"<strong>저장소 키.</strong> 저장소 하나에 여러 개의 암호와 복구 키를 둘 수 있습니다.","changelog.905de5db76c9":"<strong>복제.</strong> 저장소를 두 번째 장소로 복사하며, 상대편에 없는 것만 보냅니다.","changelog.ed05f802fa45":"<strong>다른 백업 도구.</strong> <code>freally migrate</code>로 restic, Borg, Kopia 저장소를 가져오고, <code>freally export</code>로 다시 내보냅니다.","changelog.9310ff4d82b1":"백업이 아무 말 없이 데이터를 잃을 수 있었던 경우를 포함해, 전면 검토에서 발견된 문제 15가지.","changelog.9124de6aa268":"<span class=\"release__meta\"><span class=\"release__ver\">v0.19.84</span><time class=\"release__date\" datetime=\"2026-06-27\">2026-06-27</time></span><span class=\"release__title\">첫 릴리스</span>","changelog.facf44888f54":"각 시스템의 가장 빠른 경로를 거치고, 지원하는 파일 시스템에서는 즉시 복제하며, 어떤 크기의 폴더든 메모리를 채우지 않고 스트리밍하는 <strong>바이트 단위로 정확한 복사와 이동</strong>.","changelog.36feaab53bd3":"CRC32와 xxHash3부터 SHA-256과 BLAKE3까지, 8가지 체크섬을 사용하는 <strong>복사 후 검증</strong>.","changelog.d269986b29b2":"어떤 작업이든 <strong>일시 중지, 다시 시작, 취소</strong>할 수 있고, 이미 있는 파일을 어떻게 할지 고르며, 권한 때문에 거부된 파일을 관리자 권한으로 재시도합니다.","changelog.294162447b0a":"각 복사의 진행 상황을 기록한 저널을 바탕으로 한 <strong>크래시나 재부팅 후 재개</strong>.","changelog.59d391bd4f36":"<strong>기록과 합계</strong>: 모든 작업을 기록하고, 거르고, CSV로 내보내고, 클릭 한 번으로 다시 실행합니다.","changelog.bcb57f6f639f":"<strong>필터</strong>: 포함 및 제외 패턴, 크기, 날짜, 파일 특성.","changelog.e262b2471351":"충돌 감지 기능이 있는 <strong>양방향 동기화</strong>, 미러 및 기여 모드, 그리고 저장된 모든 변경을 동기화하는 라이브 미러.","changelog.f299d8319e86":"고정 또는 일정에 따른 <strong>속도 제한</strong>.","changelog.7ba87a11a88a":"<strong>모르는 사이에 잃는 것은 없습니다</strong>: 희소 파일, 대체 데이터 스트림, 확장 속성, 인터넷에서 다운로드했다는 표시가 유지되며, Windows에서 잠긴 파일은 스냅샷에서 복사할 수 있습니다.","changelog.a0a934ff3831":"<strong>당신의 데스크톱</strong>: Windows, macOS, Linux의 오른쪽 클릭 메뉴, 어디서든 작동하는 붙여넣기 단축키, 트레이 아이콘.","changelog.2180818af954":"WebDAV, HTTP, S3 호환 API 또는 SFTP를 통한 <strong>파일 서버</strong>와, 화면이 없는 컴퓨터를 위한 <code>freally serve</code>.","changelog.d49f07823c77":"JSON Lines 출력, 문서화된 종료 코드, 실행 전에 계획할 수 있는 작업을 갖춘 <strong><code>freally</code> 명령줄</strong>.","changelog.e50cd2fc0077":"<strong>왜 느릴까요?</strong> 배지가 복사를 붙잡고 있는 원인을 알려 줍니다.","changelog.3d3204d8e967":"<strong>18개 언어</strong>, 아랍어는 오른쪽에서 왼쪽으로."};
